--
-- The images of a site (ADR-038). An asset is never deleted, since a revision may name it, and
-- nothing of it changes but its alt: its id is the hash of its bytes, and R2 holds those bytes.
CREATE TABLE `assets` (
	`id` text PRIMARY KEY NOT NULL,
	`site_id` text NOT NULL,
	`sha256` text NOT NULL,
	`format` text NOT NULL,
	`width` integer,
	`height` integer,
	`bytes` integer NOT NULL,
	`original_format` text NOT NULL,
	`original_bytes` integer NOT NULL,
	`alt` text NOT NULL,
	`filename` text NOT NULL,
	`created_by` text NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`created_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "assets_formats" CHECK("assets"."format" IN ('image/jpeg', 'image/png', 'image/webp', 'image/avif', 'image/gif', 'image/svg+xml') AND "assets"."original_format" IN ('image/jpeg', 'image/png', 'image/webp', 'image/avif', 'image/gif', 'image/svg+xml')),
	CONSTRAINT "assets_sizes" CHECK("assets"."bytes" > 0 AND "assets"."original_bytes" BETWEEN 1 AND 10485760 AND length("assets"."alt") BETWEEN 1 AND 500 AND length("assets"."filename") BETWEEN 1 AND 200 AND length("assets"."sha256") = 64)
);
--> statement-breakpoint
CREATE INDEX `assets_site_time` ON `assets` (`site_id`,`created_at`,`id`);--> statement-breakpoint
CREATE UNIQUE INDEX `assets_id_site` ON `assets` (`id`,`site_id`);--> statement-breakpoint
CREATE UNIQUE INDEX `assets_sha256` ON `assets` (`site_id`,`sha256`);
--> statement-breakpoint
CREATE TRIGGER `assets_no_delete`
BEFORE DELETE ON `assets`
BEGIN
	SELECT RAISE(ABORT, 'append-only: an asset is never deleted, since a revision may name it');
END;
--> statement-breakpoint
CREATE TRIGGER `assets_immutable`
BEFORE UPDATE OF `id`, `site_id`, `sha256`, `format`, `width`, `height`, `bytes`, `original_format`, `original_bytes`, `filename`, `created_by`, `created_at` ON `assets`
BEGIN
	SELECT RAISE(ABORT, 'append-only: only the alt of an asset changes');
END;
